<?php
 namespace QQWorld\Sales\Model\Service; class CreditmemoService implements \QQWorld\Sales\Api\CreditmemoManagementInterface { protected $creditmemoRepository; protected $commentRepository; protected $searchCriteriaBuilder; protected $filterBuilder; protected $creditmemoNotifier; protected $priceCurrency; protected $eventManager; private $resource; private $refundAdapter; private $orderRepository; private $invoiceRepository; public function __construct( \QQWorld\Sales\Api\CreditmemoRepositoryInterface $creditmemoRepository, \QQWorld\Sales\Api\CreditmemoCommentRepositoryInterface $creditmemoCommentRepository, \QQWorld\Framework\Api\SearchCriteriaBuilder $searchCriteriaBuilder, \QQWorld\Framework\Api\FilterBuilder $filterBuilder, \QQWorld\Sales\Model\Order\CreditmemoNotifier $creditmemoNotifier, \QQWorld\Framework\Pricing\PriceCurrencyInterface $priceCurrency, \QQWorld\Framework\Event\ManagerInterface $eventManager ) { $this->creditmemoRepository = $creditmemoRepository; $this->commentRepository = $creditmemoCommentRepository; $this->searchCriteriaBuilder = $searchCriteriaBuilder; $this->filterBuilder = $filterBuilder; $this->creditmemoNotifier = $creditmemoNotifier; $this->priceCurrency = $priceCurrency; $this->eventManager = $eventManager; } public function cancel($id) { throw new \QQWorld\Framework\Exception\LocalizedException(__('You can not cancel Credit Memo')); try { $creditmemo = $this->creditmemoRepository->get($id); $creditmemo->setState(\QQWorld\Sales\Model\Order\Creditmemo::STATE_CANCELED); foreach ($creditmemo->getAllItems() as $item) { $item->cancel(); } $this->eventManager->dispatch('sales_order_creditmemo_cancel', ['creditmemo' => $creditmemo]); $this->creditmemoRepository->save($creditmemo); } catch (\Exception $e) { throw new \QQWorld\Framework\Exception\LocalizedException(__('Could not cancel creditmemo'), $e); } return true; } public function getCommentsList($id) { $this->searchCriteriaBuilder->addFilters( [$this->filterBuilder->setField('parent_id')->setValue($id)->setConditionType('eq')->create()] ); $searchCriteria = $this->searchCriteriaBuilder->create(); return $this->commentRepository->getList($searchCriteria); } public function notify($id) { $creditmemo = $this->creditmemoRepository->get($id); return $this->creditmemoNotifier->notify($creditmemo); } public function refund( \QQWorld\Sales\Api\Data\CreditmemoInterface $creditmemo, $offlineRequested = false ) { $this->validateForRefund($creditmemo); $creditmemo->setState(\QQWorld\Sales\Model\Order\Creditmemo::STATE_REFUNDED); $connection = $this->getResource()->getConnection('sales'); $connection->beginTransaction(); try { $invoice = $creditmemo->getInvoice(); if ($invoice && !$offlineRequested) { $invoice->setIsUsedForRefund(true); $invoice->setBaseTotalRefunded( $invoice->getBaseTotalRefunded() + $creditmemo->getBaseGrandTotal() ); $creditmemo->setInvoiceId($invoice->getId()); $this->getInvoiceRepository()->save($creditmemo->getInvoice()); } $order = $this->getRefundAdapter()->refund( $creditmemo, $creditmemo->getOrder(), !$offlineRequested ); $this->getOrderRepository()->save($order); $this->creditmemoRepository->save($creditmemo); $connection->commit(); } catch (\Exception $e) { $connection->rollBack(); throw new \QQWorld\Framework\Exception\LocalizedException(__($e->getMessage())); } return $creditmemo; } protected function validateForRefund(\QQWorld\Sales\Api\Data\CreditmemoInterface $creditmemo) { if ($creditmemo->getId()) { throw new \QQWorld\Framework\Exception\LocalizedException( __('We cannot register an existing credit memo.') ); } $baseOrderRefund = $this->priceCurrency->round( $creditmemo->getOrder()->getBaseTotalRefunded() + $creditmemo->getBaseGrandTotal() ); if ($baseOrderRefund > $this->priceCurrency->round($creditmemo->getOrder()->getBaseTotalPaid())) { $baseAvailableRefund = $creditmemo->getOrder()->getBaseTotalPaid() - $creditmemo->getOrder()->getBaseTotalRefunded(); throw new \QQWorld\Framework\Exception\LocalizedException( __( 'The most money available to refund is %1.', $creditmemo->getOrder()->formatBasePrice($baseAvailableRefund) ) ); } return true; } private function getRefundAdapter() { if ($this->refundAdapter === null) { $this->refundAdapter = \QQWorld\Framework\App\ObjectManager::getInstance() ->get(\QQWorld\Sales\Model\Order\RefundAdapterInterface::class); } return $this->refundAdapter; } private function getResource() { if ($this->resource === null) { $this->resource = \QQWorld\Framework\App\ObjectManager::getInstance() ->get(\QQWorld\Framework\App\ResourceConnection::class); } return $this->resource; } private function getOrderRepository() { if ($this->orderRepository === null) { $this->orderRepository = \QQWorld\Framework\App\ObjectManager::getInstance() ->get(\QQWorld\Sales\Api\OrderRepositoryInterface::class); } return $this->orderRepository; } private function getInvoiceRepository() { if ($this->invoiceRepository === null) { $this->invoiceRepository = \QQWorld\Framework\App\ObjectManager::getInstance() ->get(\QQWorld\Sales\Api\InvoiceRepositoryInterface::class); } return $this->invoiceRepository; } } 